export const BOOZY: string[] = ['أنجلز شير','بلاك فانتوم','سترايت تو هيفن','إنتوكسيكيتيد','أبل براندي','إليفينث آور','بنتلي فور مين','دورو','خمرة','درهم','جاز كلوب','باي ذا فايربليس','فانيي فاتال','بيتر بيتش','سبيريتوز دبل فانيل','بربري لندن','ناكسوس','سايد إيفكت','ريهاب','باوندلس','سي إتش مين','بوس بوتلد إكسير','إنيغما بور أوم','كايالي فانيلا ٢٨','إيطاليكا','ون مليون بريفيه','شيرغي','غران سوار'];

export function applyBoozy(perfumes: Perfume[]): Perfume[] {
  return perfumes.map((d) => {
    if (BOOZY.some((b) => d.n.includes(b))) return { ...d, c: 'boozy' };
    return d;
  });
}

